mansion_state_auditor.agent_input_schema:
{
  "type": "object",
  "properties": {
    "current_observation": {
      "type": "string",
      "description": "The current game screen, position, and any text box messages."
    },
    "recent_history": {
      "type": "string",
      "description": "The recent sequence of movements, switch toggles, and map transitions."
    },
    "hypotheses": {
      "type": "string",
      "description": "Active hypotheses about switch persistence and gate configurations."
    }
  },
  "required": ["current_observation", "recent_history", "hypotheses"]
}

mansion_state_auditor.agent_output_schema:
{
  "type": "object",
  "properties": {
    "analysis": {
      "type": "string",
      "description": "A logical, step-by-step analysis of the current state and discrepancies."
    },
    "gate_matrix_updates": {
      "type": "string",
      "description": "Recommended updates or corrections to the Switch Matrix based on evidence."
    },
    "next_strategic_steps": {
      "type": "string",
      "description": "Recommended immediate actions to test or progress."
    }
  },
  "required": ["analysis", "gate_matrix_updates", "next_strategic_steps"]
}
